"use client";
import { useState } from "react";
import businessStyles from "@/components/business.module.css";
import { useRouter } from "next/navigation";
import { userFeedback } from "@/lib/user-feedback";
import { Button } from "@/components/ui/button";
import { CheckboxField, TextField } from "@/components/ui/form-controls";
import { Disclosure } from "@/components/ui/disclosure";
import { FeedbackMessage } from "@/components/ui/feedback-message";
type Customer = { id: string; code: string; name: string; active: boolean };
type Factory = { id: string; name: string; address: string; contactName?: string | null; contactPhone?: string | null };

export function CustomerRecordForm({ customer }: { customer: Customer }) { const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false); const router = useRouter(); async function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); if (busy) return; const form = new FormData(event.currentTarget); setBusy(true); setMessage(""); try { const response = await fetch(`/api/customers/${customer.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ code: form.get("code"), name: form.get("name"), active: form.get("active") === "on" }) }); if (response.ok) { setMessage("客户档案已保存。"); router.refresh(); } else setMessage(userFeedback.retry("保存客户档案")); } catch { setMessage(userFeedback.network); } finally { setBusy(false); } } return <Disclosure className={businessStyles["record-editor"]} title="编辑客户档案"><form onSubmit={submit}><TextField label="客户编码" name="code" defaultValue={customer.code} required disabled={busy}/><TextField label="客户名称" name="name" defaultValue={customer.name} required disabled={busy}/><CheckboxField className={businessStyles["record-editor__check"]} name="active" defaultChecked={customer.active} disabled={busy}>启用此客户</CheckboxField><Button type="submit" size="small" wide="mobile" disabled={busy}>{busy ? "正在保存…" : "保存客户档案"}</Button>{message && <FeedbackMessage as="small">{message}</FeedbackMessage>}</form></Disclosure>; }

export function FactoryRecordForm({ customerId, factory }: { customerId: string; factory: Factory }) { const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false); const router = useRouter(); async function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); if (busy) return; const form = new FormData(event.currentTarget); const text = (name: string) => String(form.get(name) || "") || null; setBusy(true); setMessage(""); try { const response = await fetch(`/api/customers/${customerId}/factories/${factory.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: form.get("name"), address: form.get("address"), contactName: text("contactName"), contactPhone: text("contactPhone") }) }); if (response.ok) { setMessage("工厂档案已保存。"); router.refresh(); } else setMessage(userFeedback.retry("保存工厂档案")); } catch { setMessage(userFeedback.network); } finally { setBusy(false); } } return <Disclosure className={businessStyles["record-editor"]} title="编辑工厂信息"><form onSubmit={submit}><TextField label="工厂名称" name="name" defaultValue={factory.name} required disabled={busy}/><TextField label="装柜地址" name="address" defaultValue={factory.address} required disabled={busy}/><TextField label="联系人（可选）" name="contactName" defaultValue={factory.contactName || ""} disabled={busy}/><TextField label="联系电话（可选）" name="contactPhone" defaultValue={factory.contactPhone || ""} disabled={busy}/><Button type="submit" size="small" wide="mobile" disabled={busy}>{busy ? "正在保存…" : "保存工厂信息"}</Button>{message && <FeedbackMessage as="small">{message}</FeedbackMessage>}</form></Disclosure>; }
